import logo from './logo.svg';
import './App.css';

function employeeLogin() {
  return (
    <div className="page">
        <form>
          <h2>Welcome</h2>
          <h1>Create your Account</h1>
          <label>
            Username
          </label>
          <label>
            Email Adress
          </label>
          <label>
            Phone Number
          </label>
          <label>
            Password
          </label>
          <label>
            Confirm Password
          </label>
        </form>
    </div>
  );
}
// ReactDOM.render(App, document.getElementById("App"))


export default employeeLogin;
